const VIEW_BOXES: Record<VersoLogoVariant, string> = {
    mark: '0 0 32 32',
    full: '0 0 104 32',
};

// The Verso logo: an open book seen from the spine, drawn as a V, with an optional wordmark.
export function VersoLogo({
    variant = 'mark',
    title = 'Verso',
    className,
    ...props
}: Props) {
    const titleId = useId();

    return (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox={VIEW_BOXES[variant]}
            role="img"
            aria-labelledby={titleId}
            data-variant={variant}
            className={cn('shrink-0', className)}
            {...props}
        >
            <title id={titleId}>{title}</title>
            <g fill="currentColor">
                <path d={MARK_PATH} />
                {variant === 'full' && <path d={WORDMARK_PATH} />}
            </g>
        </svg>
    );
}

export default VersoLogo;
